examples.source:
Table users {
  id integer [pk, increment]
  email varchar(255) [not null, unique]
  created_at timestamp [default: `now()`]
}
Table posts {
  id integer [pk]
  user_id integer [not null, ref: > users.id]
  title varchar
}

Table orders {
  id int [pk]
  customer_id int
}
Table customers {
  id int [pk]
}
Table lines {
  order_id int
  sku varchar
  qty int
  indexes {
    (order_id, sku) [pk]
  }
}
Ref fk_order: orders.customer_id > customers.id [delete: cascade]
Ref: lines.order_id > orders.id

Enum order_status {
  pending
  shipped
  cancelled
}
Table orders {
  id int [pk]
  status order_status
}
Table audit {
  id int [pk]
}
TableGroup core {
  orders
  audit
}

Table core.users {
  id int [pk]
  name varchar [note: 'Display name']
}
Table core.sessions {
  id int [pk]
  user_id int [ref: > core.users.id]
}
Table billing.invoices [headercolor: #3498DB] {
  id int [pk]
  user_id int [ref: > core.users.id]
}

Table "student" {
  id int [pk]
  "full name" varchar
}
Table "course" {
  id int [pk]
}
Table "enrolment" {
  student_id int [ref: > student.id]
  course_id int [ref: > course.id]
  Note: 'join table'
}
